// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

/**
 * Comparison operator vocabulary of the fragment tier. Deliberately its own enum: the engine has two other operator
 * orderings ({@code Compare.CompareOp} ordinals and the emitter's op-int table), and a silent ordinal mismatch between
 * them is exactly the naming hazard the fragment design forbids.
 */
public enum FragmentCompareOp {
	EQ,
	NE,
	LT,
	LE,
	GT,
	GE;

	/** Applies this operator to a three-way comparison result. */
	public boolean test(int comparison) {
		switch (this) {
		case EQ:
			return comparison == 0;
		case NE:
			return comparison != 0;
		case LT:
			return comparison < 0;
		case LE:
			return comparison <= 0;
		case GT:
			return comparison > 0;
		default:
			return comparison >= 0;
		}
	}

	/** The operator with operand sides swapped ({@code a < b} equals {@code b > a}). */
	public FragmentCompareOp flip() {
		switch (this) {
		case LT:
			return GT;
		case LE:
			return GE;
		case GT:
			return LT;
		case GE:
			return LE;
		default:
			return this;
		}
	}
}
